  MINIMAL [label="✗ minimal descriptions", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  OVERLAP [label="✗ near-identical\ndescriptions", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
